<?php
require_once __DIR__.'/includes/bootstrap.php';
$id=(int)($_GET['id']??0);$lesson=null;$course=null;if($id>0){try{$q=$db->prepare("SELECT l.*,c.title course_title,c.slug course_slug FROM learning_lessons l JOIN learning_courses c ON c.id=l.course_id WHERE l.id=? AND l.enabled=1 LIMIT 1");$q->execute([$id]);$lesson=$q->fetch(PDO::FETCH_ASSOC)?:null;}catch(Throwable){}}if(!$lesson){http_response_code(404);exit('Lesson not found.');}
$user=lh_user();if($_SERVER['REQUEST_METHOD']==='POST'&&$user){try{$q=$db->prepare("INSERT INTO learning_progress(user_id,lesson_id,completed,progress_percent) VALUES(?,?,1,100) ON DUPLICATE KEY UPDATE completed=1,progress_percent=100");$q->execute([(int)$user['id'],$id]);}catch(Throwable){}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=lh_h($lesson['title'])?> — Learning Hub</title><style>body{margin:0;font-family:Inter,Arial;background:#f7f9fd;color:#172033}.wrap{width:min(850px,calc(100% - 28px));margin:auto}.top{padding:40px 0 20px}.top a{color:#635bff;font-size:13px;font-weight:800}.article{background:#fff;border:1px solid #e5e8ef;border-radius:20px;padding:30px;margin-bottom:50px}.article h1{font-size:34px;margin:0 0 22px}.content{font-size:15px;line-height:1.85;color:#384359}.video{margin:20px 0;padding:15px;background:#f0efff;border-radius:12px}.done{margin-top:25px}.btn{border:0;background:#635bff;color:#fff;border-radius:10px;padding:11px 15px;font-weight:800}.login{font-size:13px;color:#707b8e}</style></head><body><main class="wrap"><div class="top"><a href="/learning-hub/course.php?slug=<?=rawurlencode($lesson['course_slug'])?>">← <?=lh_h($lesson['course_title'])?></a></div><article class="article"><h1><?=lh_h($lesson['title'])?></h1><?php if(!empty($lesson['video_url'])):?><div class="video"><a href="<?=lh_h($lesson['video_url'])?>" target="_blank" rel="noopener">▶ Open lesson video</a></div><?php endif;?><div class="content"><?=nl2br(lh_h($lesson['content']??''))?></div><div class="done"><?php if($user):?><form method="post"><button class="btn" type="submit">✓ Mark lesson complete</button></form><?php else:?><span class="login">Login to save your learning progress.</span><?php endif;?></div></article></main></body></html>
